import React, { useState } from 'react';

function safeDisplay(value, digits = 2) {
  if (value === undefined || value === null || Number.isNaN(value)) {
    return "N/A";
  }
  return typeof value === 'number' ? value.toFixed(digits) : value;
}

function resolveFitness(entry) {
  if (!entry) return undefined;
  if (typeof entry.fitness === 'number') return entry.fitness;
  if (typeof entry.score === 'number') return entry.score;
  if (typeof entry.final_fitness === 'number') return entry.final_fitness;
  return undefined;
}

const RunGA = ({ setSelectedStrategyForInspection }) => {
  const [populationSize, setPopulationSize] = useState(50);
  const [generations, setGenerations] = useState(20);
  const [mutationRate, setMutationRate] = useState(0.1);
  const [seed, setSeed] = useState(42);
  const [gaResult, setGaResult] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const resolvePeakGeneration = (result) => {
    const direct = result?.global_best_generation ?? result?.generation_found;
    if (direct !== undefined && direct !== null) return direct;
    const history = result?.generation_history;
    if (!Array.isArray(history) || history.length === 0) return null;
    let bestIdx = 0;
    let bestFitness = Number.NEGATIVE_INFINITY;
    history.forEach((g, idx) => {
      const s = resolveFitness(g) ?? 0;
      if (s > bestFitness) {
        bestFitness = s;
        bestIdx = idx;
      }
    });
    return bestIdx;
  };

  const handleRunGA = async () => {
    setLoading(true);
    setError(null);
    setGaResult(null);

    try {
      const response = await fetch('http://localhost:8000/run_ga');

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.message || 'Failed to run GA');
      }

      const data = await response.json();
      console.log("FULL RESPONSE:", data);
      console.log("UI_SCORE_DEBUG", data?.global_best);
      setGaResult(data);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="p-4">
      <h2 className="text-2xl font-semibold mb-4">Run Genetic Algorithm</h2>

      <div className="grid grid-cols-2 gap-4 mb-6">
        <div>
          <label className="block text-gray-700 text-sm font-bold mb-2" htmlFor="population_size">
            Population Size:
          </label>
          <input
            type="number"
            id="population_size"
            className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline"
            value={populationSize}
            onChange={(e) => setPopulationSize(e.target.value)}
          />
        </div>
        <div>
          <label className="block text-gray-700 text-sm font-bold mb-2" htmlFor="generations">
            Generations:
          </label>
          <input
            type="number"
            id="generations"
            className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline"
            value={generations}
            onChange={(e) => setGenerations(e.target.value)}
          />
        </div>
        <div>
          <label className="block text-gray-700 text-sm font-bold mb-2" htmlFor="mutation_rate">
            Mutation Rate:
          </label>
          <input
            type="number"
            id="mutation_rate"
            step="0.01"
            className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline"
            value={mutationRate}
            onChange={(e) => setMutationRate(e.target.value)}
          />
        </div>
        <div>
          <label className="block text-gray-700 text-sm font-bold mb-2" htmlFor="seed">
            Seed:
          </label>
          <input
            type="number"
            id="seed"
            className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline"
            value={seed}
            onChange={(e) => setSeed(e.target.value)}
          />
        </div>
      </div>

      <button
        className="bg-blue-500 hover:bg-blue-700 text-white font-bold py-2 px-4 rounded focus:outline-none focus:shadow-outline"
        onClick={handleRunGA}
        disabled={loading}
      >
        {loading ? 'Running GA...' : 'Run GA'}
      </button>

      {error && <p className="text-red-500 mt-4">Error: {error}</p>}

      {gaResult && (
        <div className="mt-6">
          <div className="bg-yellow-50 border border-yellow-200 rounded-md p-4 mb-4">
            <h3 className="text-xl font-semibold mb-2">🏆 Global Best Strategy</h3>
            <p><span className="font-semibold">Fitness:</span> {safeDisplay(resolveFitness(gaResult.global_best), 6)}</p>
            <p><span className="font-semibold">Avg PnL:</span> {safeDisplay(gaResult.global_best?.avg, 6)}</p>
            <p><span className="font-semibold">Std Dev:</span> {safeDisplay(gaResult.global_best?.std, 6)}</p>
            <p><span className="font-semibold">Found at Generation:</span> {resolvePeakGeneration(gaResult) ?? 'N/A'}</p>
          </div>

          <div className="bg-blue-50 border border-blue-200 rounded-md p-4 mb-4">
            <h3 className="text-xl font-semibold mb-2">📍 Final Generation Best</h3>
            <p><span className="font-semibold">Fitness:</span> {safeDisplay(resolveFitness(gaResult.final_generation_best ?? gaResult.final_gen_best), 6)}</p>
            <p><span className="font-semibold">Avg PnL:</span> {safeDisplay((gaResult.final_generation_best ?? gaResult.final_gen_best)?.avg, 6)}</p>
            <p><span className="font-semibold">Std Dev:</span> {safeDisplay((gaResult.final_generation_best ?? gaResult.final_gen_best)?.std, 6)}</p>
          </div>

          <h3 className="text-xl font-semibold mb-3">Best Strategies</h3>
          <div className="overflow-x-auto">
            <table className="min-w-full bg-white border border-gray-300">
              <thead>
                <tr>
                  <th className="py-2 px-4 border-b text-left">Strategy ID</th>
                  <th className="py-2 px-4 border-b text-left">Fitness</th>
                  <th className="py-2 px-4 border-b text-left">Avg PNL</th>
                  <th className="py-2 px-4 border-b text-left">Std Dev</th>
                  <th className="py-2 px-4 border-b text-left">Class</th>
                </tr>
              </thead>
              <tbody>
                {gaResult.results && gaResult.results.map((row) => {
                  console.log("ROW:", row);
                  return (
                  <tr
                    key={row.strategy_id}
                    className="cursor-pointer hover:bg-gray-100"
                    onClick={() => setSelectedStrategyForInspection(row.strategy_id, seed)}
                  >
                    <td className="py-2 px-4 border-b">{row.strategy_id}</td>
                    <td className="py-2 px-4 border-b">{safeDisplay(resolveFitness(row), 6)}</td>
                    <td className="py-2 px-4 border-b">{safeDisplay(row.avg, 6)}</td>
                    <td className="py-2 px-4 border-b">{safeDisplay(row.std, 6)}</td>
                    <td className="py-2 px-4 border-b">{row.classification}</td>
                  </tr>
                  );
                })}
              </tbody>
            </table>
          </div>

          <h3 className="text-xl font-semibold mt-6 mb-3">Generation History (Best Fitness)</h3>
          <div className="bg-gray-50 p-4 rounded-md">
            <p className="mb-2 text-sm font-semibold text-amber-700">
              ⭐ Peak at Gen {resolvePeakGeneration(gaResult) ?? 'N/A'}
            </p>
            {gaResult.generation_history && gaResult.generation_history.length > 0 ? (
              <div className="text-sm">
                {/* Simple text-based line chart representation */}
                {gaResult.generation_history.map((gen, index) => (
                  <div key={index} className="flex items-center mb-1">
                    <span className="w-16 text-right mr-2">Gen {index}:</span>
                    <span className="w-24 text-blue-600">{'█'.repeat(Math.max(0, Math.min(50, Math.floor((resolveFitness(gen) ?? 0) * 10))))}</span> {/* Scale to 50 blocks max, normalized */}
                    <span className="ml-2">{safeDisplay(resolveFitness(gen), 6)}</span>
                  </div>
                ))}
              </div>
            ) : (
              <p>No generation history available.</p>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default RunGA;
